     }
 }

+TEST_CASE_TEMPLATE("enum integer serialization" * doctest::test_suite("udt"), Json,
+                   nlohmann::json, nlohmann::ordered_json)
+{
+    SECTION("unsigned 64-bit scoped enum")
+    {
+        enum class book_id : std::uint64_t {};
+        const std::uint64_t values[] =
+        {
+            1,
+            std::uint64_t{1} << 63,
+            (std::numeric_limits<std::uint64_t>::max)() - 1,
+            (std::numeric_limits<std::uint64_t>::max)()
+        };
+        for (const auto value : values)
+        {
+            const auto id = static_cast<book_id>(value);
+            const Json j = id;
+            CHECK(j > 0u);
+            CHECK(j.is_number_unsigned());
+            CHECK(j.dump() == std::to_string(value));
+            CHECK(j.template get<book_id>() == id);
+            CHECK(Json::parse(j.dump()).template get<book_id>() == id);
+        }
+    }
+
+    SECTION("unsigned 32-bit unscoped enum")
+    {
+        enum book_id : std::uint32_t { first = 0, last = 0xFFFFFFFFu };
+        for (const auto id : {first, last})
+        {
+            const Json j = id;
+            CHECK(j.is_number_unsigned());
+            CHECK(j.dump() == std::to_string(static_cast<std::uint32_t>(id)));
+            CHECK(j.template get<book_id>() == id);
+        }
+    }
+
+    SECTION("signed 64-bit scoped enum")
+    {
+        enum class book_id : std::int64_t {};
+        const std::int64_t values[] =
+        {
+            (std::numeric_limits<std::int64_t>::min)(), -2, 0,
+            (std::numeric_limits<std::int64_t>::max)()
+        };
+        for (const auto value : values)
+        {
+            const auto id = static_cast<book_id>(value);
+            const Json j = id;
+            CHECK(j.type() == Json::value_t::number_integer);
+            CHECK(j.dump() == std::to_string(value));
+            CHECK(j.template get<book_id>() == id);
+        }
+    }
+}
+
 namespace udt
